class CoursesControllerCourseControllerTest { @Test void rejectsAbsentToken(){var controller=new CoursesController(new CourseService(new Empty(),Clock.systemUTC()),new ApiProperties(new ApiProperties.Cors(List.of()),new ApiProperties.Security("a","b","c","d"),new ApiProperties.Course("secret")));assertThat(controller.upsert(null,new CoursesController.ImportRequest(List.of())).getStatusCode().value()).isEqualTo(403);} private static final class Empty implements CourseRepository {public CourseCategory saveCategory(CourseCategory x){return x;}public Optional<CourseCategory> findCategoryBySlug(String x){return Optional.empty();}public CourseLesson saveLesson(CourseLesson x){return x;}public Optional<CourseLesson> findLessonBySourceIdentity(String x){return Optional.empty();}public Optional<CourseLesson> findLessonByIdentity(String x){return Optional.empty();}public List<CourseCategory> categories(){return List.of();}public List<CourseLesson> lessons(String a,String b,String c){return List.of();}} }
